using System.Collections.Generic;using UnityEngine;
namespace Blocklands
{
    public class FloodResident:MonoBehaviour
    {
        public Sandbox Game;public bool Downed {get;private set;}public bool Assigned;public float CareProgress;public float RetryAt;
        public bool NeedsCare=>Downed||SwordDownedNpc.IsDown(transform);
        Transform figure;BoxCollider proneCollider;Collider[] bodies;bool[] enabledBefore;
        public static bool IsDown(Transform t){if(SwordDownedNpc.IsDown(t))return true;var f=t.GetComponent<FloodResident>();return f!=null&&f.Downed;}
        public void KnockDown(){if(Downed)return;Downed=true;Assigned=false;CareProgress=0;RetryAt=0;if(figure==null){figure=new GameObject("海浪冲倒姿势").transform;figure.SetParent(transform,false);var models=new List<Transform>();foreach(Transform child in transform)if(child!=figure&&(child.GetComponent<Renderer>()!=null||child.GetComponentInChildren<Renderer>()!=null))models.Add(child);foreach(var m in models)m.SetParent(figure,false);}var list=new List<Collider>();foreach(var c in GetComponents<Collider>())if(c!=proneCollider)list.Add(c);bodies=list.ToArray();enabledBefore=new bool[bodies.Length];for(int i=0;i<bodies.Length;i++){enabledBefore[i]=bodies[i].enabled;bodies[i].enabled=false;}if(proneCollider==null){proneCollider=gameObject.AddComponent<BoxCollider>();proneCollider.center=new Vector3(0,.32f,-.75f);proneCollider.size=new Vector3(.7f,.58f,1.85f);}proneCollider.enabled=true;figure.localPosition=Vector3.up*.3f;figure.localRotation=Quaternion.Euler(-90,0,0);Physics.SyncTransforms();}
        public void Recover(){if(!NeedsCare)return;if(Downed){Downed=false;figure.localPosition=Vector3.zero;figure.localRotation=Quaternion.identity;if(proneCollider!=null)proneCollider.enabled=false;for(int i=0;i<bodies.Length;i++)if(bodies[i]!=null)bodies[i].enabled=enabledBefore[i];}GetComponent<SwordDownedNpc>()?.Recover();Assigned=false;CareProgress=1;RetryAt=0;Physics.SyncTransforms();}
    }
    public class FloodMedic:MonoBehaviour
    {
        public Sandbox Game;public FloodResident Patient {get;private set;}public bool Flying {get;private set;}
        Transform pod,beam;Vector3 landing;int stage;float age,care;bool airborne;Collider body;float cruise;
        public void Initialize(Sandbox g){Game=g;body=GetComponent<Collider>();var art=GetComponent<RoyalArt>();pod=new GameObject("医护救援悬浮艇").transform;pod.SetParent(transform,false);var pa=pod.gameObject.AddComponent<RoyalArt>();pa.Piece("救援艇平台",new Vector3(0,-.18f,0),new Vector3(2.3f,.2f,1.6f),new Color(.55f,.84f,.93f),PrimitiveType.Cylinder);foreach(float x in new[]{-.95f,.95f})foreach(float z in new[]{-.55f,.55f})pa.Piece("医疗悬浮器",new Vector3(x,-.23f,z),new Vector3(.38f,.15f,.38f),new Color(.22f,.46f,.65f),PrimitiveType.Cylinder);pod.gameObject.SetActive(false);beam=art.Piece("医疗救援光束（游戏效果）",Vector3.zero,new Vector3(.035f,1,.035f),new Color(.35f,.88f,.99f),PrimitiveType.Cylinder);beam.gameObject.SetActive(false);art.Piece("蓝色急救包",new Vector3(.48f,.7f,.22f),new Vector3(.35f,.3f,.25f),new Color(.3f,.7f,.9f));}
        public bool Assign(FloodResident patient){if(Patient!=null||patient==null||!patient.NeedsCare||patient.Assigned)return false;Patient=patient;patient.Assigned=true;patient.CareProgress=0;age=care=0;stage=0;ChooseLanding(patient.transform.position,out landing);airborne=true;cruise=Mathf.Max(transform.position.y,landing.y)+5;for(int i=0;i<=8;i++){Vector3 sample=Vector3.Lerp(transform.position,landing,i/8f);foreach(var hit in Physics.RaycastAll(new Vector3(sample.x,160,sample.z),Vector3.down,160,~(1<<2),QueryTriggerInteraction.Ignore))if(hit.collider.transform!=transform&&!hit.collider.transform.IsChildOf(transform))cruise=Mathf.Max(cruise,hit.point.y+4);}Flying=true;if(body!=null)body.enabled=false;pod.gameObject.SetActive(true);return true;}
        bool ChooseLanding(Vector3 p,out Vector3 goal){float altitude=SkyHouse.FloorHeight(SkyHouse.RoofFloor)+14;foreach(var d in new[]{Vector3.right*1.6f,Vector3.left*1.6f,Vector3.forward*1.8f,Vector3.back*1.8f}){Vector3 origin=p+d;origin.y=altitude;if(Physics.Raycast(origin,Vector3.down,out var hit,altitude-p.y+2,~(1<<2),QueryTriggerInteraction.Ignore)&&hit.point.y>=p.y-.6f&&hit.point.y<=p.y+4.5f){goal=hit.point+Vector3.up*.04f;return true;}}goal=p+Vector3.right*1.8f;return false;}
        bool FlyTo(Vector3 goal,float dt){transform.position=Vector3.MoveTowards(transform.position,goal,50*dt);return Vector3.Distance(transform.position,goal)<.05f;}
        public void Advance(float dt){if(Game==null||Game.Paused||Patient==null)return;if(!Patient.NeedsCare){Finish(false);return;}age+=dt;if(age>30){Patient.RetryAt=0;Finish(false);return;}
            Vector3 target=landing;if(airborne){float altitude=cruise;if(stage==0){target=new Vector3(transform.position.x,altitude,transform.position.z);if(FlyTo(target,dt))stage=1;}else if(stage==1){target=new Vector3(landing.x,altitude,landing.z);if(FlyTo(target,dt))stage=2;}else if(stage==2){if(FlyTo(landing,dt)){stage=3;Flying=false;pod.gameObject.SetActive(false);if(body!=null)body.enabled=true;}}}
            else if(stage<3){foreach(var door in Game.World.GetComponentsInChildren<HomeFixture>())if(door.Kind==Block.IronDoor&&!door.State.Open&&Vector3.Distance(door.transform.position,transform.position)<3)door.Toggle();NpcNavigation.Ensure(transform).MoveTo(landing,2.5f,dt);if(Vector3.Distance(transform.position,landing)<.6f)stage=3;}
            if(stage==3){if(Vector3.Distance(transform.position,Patient.transform.position)>6){Finish(false);return;}care+=dt;Patient.CareProgress=Mathf.Clamp01(care/8);Vector3 look=Patient.transform.position-transform.position;look.y=0;if(look.sqrMagnitude>.1f)transform.rotation=Quaternion.LookRotation(look);foreach(Transform t in transform)if(t.name=="手臂")t.localRotation=Quaternion.Euler(-40+Mathf.Sin(care*5)*8,0,0);Vector3 a=transform.position+Vector3.up,b=Patient.transform.position+Vector3.up*.45f;beam.gameObject.SetActive(true);beam.position=(a+b)*.5f;beam.rotation=Quaternion.FromToRotation(Vector3.up,b-a);beam.localScale=new Vector3(.035f,Vector3.Distance(a,b)*.5f,.035f);if(care>=8){var recovered=Patient;Patient.Recover();Game.FloodPatientRecovered(recovered);Finish(true);}}
        }
        void Finish(bool healed){if(Patient!=null)Patient.Assigned=false;Patient=null;Flying=false;pod.gameObject.SetActive(false);beam.gameObject.SetActive(false);if(body!=null)body.enabled=true;age=care=0;stage=0;}
    }
    public partial class Sandbox
    {
        readonly List<FloodResident> floodResidents=new List<FloodResident>();readonly List<FloodMedic> floodMedics=new List<FloodMedic>();Transform floodCareRoot;int floodRescued;
        public const int MedicalTeamSize=6;
        public int FloodDownCount{get{int n=0;foreach(var f in floodResidents)if(f!=null&&f.NeedsCare)n++;return n;}}public int FloodRescuedCount=>floodRescued;
        public void RegisterMedicalPatient(Transform t){if(World.Region!=1||t==null||!t.IsChildOf(villagePeople.transform)||t.GetComponent<FloodMedic>()!=null)return;var f=t.GetComponent<FloodResident>()??t.gameObject.AddComponent<FloodResident>();f.Game=this;if(!floodResidents.Contains(f))floodResidents.Add(f);}
        void BuildFloodResidents(){floodResidents.Clear();floodRescued=0;if(World.Region!=1)return;foreach(var v in FindObjectsByType<Villager>())if(!v.IsFriend)RegisterMedicalPatient(v.transform);foreach(var r in FindObjectsByType<SkyResidentInfo>())RegisterMedicalPatient(r.transform);foreach(var c in FindObjectsByType<CommunityCitizen>())if(c.Role=="农民")RegisterMedicalPatient(c.transform);}
        public void ApplyFloodImpact(float front,float level){if(World.Region!=1)return;foreach(var f in floodResidents)if(f!=null&&!f.NeedsCare){var p=f.transform.position;if(p.y>=0&&p.y<110&&p.x>=0&&p.x<96&&p.z>=0&&p.z<front&&p.y+.7f<level)f.KnockDown();}}
        void BuildFloodMedics(){if(floodCareRoot!=null)return;floodCareRoot=new GameObject("村庄医护救援队").transform;floodCareRoot.SetParent(villagePeople.transform,false);for(int i=0;i<MedicalTeamSize;i++){var a=MakeCommunityPerson(floodCareRoot,"救援护士 "+(i+1),new Vector3(44+i%6*2,15.04f,73+i/6*3),Color.white,"医生");a.GetComponent<CommunityCitizen>().enabled=false;var medic=a.gameObject.AddComponent<FloodMedic>();medic.Initialize(this);floodMedics.Add(medic);}}
        public void TickFloodCare(float dt){if(Paused||World.Region!=1||TsunamiActive||FloodDownCount==0)return;BuildFloodMedics();foreach(var m in floodMedics){if(m==null)continue;if(m.Patient==null){FloodResident best=null;float distance=float.PositiveInfinity;foreach(var f in floodResidents)if(f!=null&&f.NeedsCare&&!f.Assigned&&Time.unscaledTime>=f.RetryAt){float d=Vector3.Distance(m.transform.position,f.transform.position);if(d<distance){distance=d;best=f;}}if(best!=null)m.Assign(best);}m.Advance(Mathf.Min(.2f,dt));}}
        public void FloodPatientRecovered(FloodResident patient=null){floodRescued++;if(patient!=null){string key=CombatNpcKey(patient.transform);bool attacked=NpcCombatStates.RemoveAll(n=>n.region==World.Region&&n.key==key)>0;if(attacked||Theft.Count>0)AlertVillage();Save();}Notice="医护已经扶起一位村民；还有"+FloodDownCount+"人等待救援。";}
        void ResetFloodCare(){if(floodCareRoot!=null){floodCareRoot.gameObject.SetActive(false);Destroy(floodCareRoot.gameObject);}floodCareRoot=null;floodMedics.Clear();floodResidents.Clear();floodRescued=0;}
    }
}
